const ControlFeature={id:"control",name:"Tools",icon:"construction",async render(){const e=await DB.getSetting("pitchDemoSeeded",!1);return`\n      <div class="fade-in notebook-page control-center">\n        <div class="notebook-brand">\n          <div class="notebook-logo">${Utils.escapeHtml((CONFIG.companyName||"AdvisorOS").trim())}</div>\n        </div>\n\n        <section class="notebook-section">\n          <div class="notebook-title">\n            <h1>TOOLS</h1>\n          </div>\n          <p class="control-intro">Fast actions, money tools and route helpers, kept off Home so the day stays calm.</p>\n        </section>\n\n        ${this.renderSection("Today actions",[{icon:"add",label:"Add Visit",action:"App.navigate('appointments', {action: 'add'})"},{icon:"route",label:"Log Mileage",action:"MoneyFeature.openMileageModal()"},{icon:"receipt_long",label:"Log Expense",action:"MoneyFeature.openExpenseModal()"},{icon:"fact_check",label:"End of Day",action:"TodayFeature.openEODModal()"}])}\n\n        ${this.renderSection("Plan & measure",[{icon:"map",label:"Route Planner",action:"App.navigate('route')"},{icon:"straighten",label:"Measure",action:"ControlFeature.openMeasurePicker()"},{icon:"document_scanner",label:"Scan Document",action:"App.navigate('ocr')"}])}\n\n        ${this.renderSection("Account",[{icon:"settings",label:"Settings",action:"App.navigate('settings')"},{icon:"cloud_download",label:"Export Backup",action:"ExportService.exportBackup()"},...e?[{icon:"delete_sweep",label:"Remove Demo Data",action:"ControlFeature.confirmClearPitchDemo()"}]:[]])}\n      </div>\n    `},renderSection:(e,t)=>`\n      <section class="notebook-section control-section">\n        <div class="notebook-title">\n          <h2>${Utils.escapeHtml(e)}</h2>\n        </div>\n        <div class="control-grid">\n          ${t.map(e=>`\n            <button class="control-tile" type="button" onclick="${e.action}">\n              <span class="material-symbols-rounded">${e.icon}</span>\n              <span>${Utils.escapeHtml(e.label)}</span>\n            </button>\n          `).join("")}\n        </div>\n      </section>\n    `,at(e,t){const[n,o]=t.split(":").map(Number),a=new Date(e);return a.setHours(n,o,0,0),a.toISOString()},async openMeasurePicker(){let e=[];try{const t=await DB.getUpcomingAppointments(30);e=[...await DB.getAppointmentsForDate(Utils.getToday().toISOString()),...t].filter((e,t,n)=>n.findIndex(t=>t.id===e.id)===t).slice(0,15)}catch(e){console.error("Measure picker failed:",e)}if(0===e.length)return Toast.show("Add a visit first, then measure against it","info"),void App.navigate("appointments",{action:"add"});const t=`<div class="sheet-handle"></div>\n      <div class="sheet-header"><h3>Measure for which visit?</h3><button class="btn btn-ghost btn-sm" onclick="App.closeModal()"><span class="material-symbols-rounded">close</span></button></div>\n      <div class="sheet-body">\n        <div style="display:flex;flex-direction:column;gap:8px;">\n          ${e.map(e=>`\n            <button class="list-item" style="border:1px solid var(--border-light);border-radius:8px;text-align:left;" onclick="App.closeModal(); App.navigate('measure', {appointmentId: ${e.id}})">\n              <span class="material-symbols-rounded" style="color:var(--primary);margin-right:12px;">straighten</span>\n              <span style="flex:1;min-width:0;">\n                <span style="display:block;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${Utils.escapeHtml(e.clientName||"Unknown")}</span>\n                <span style="display:block;font-size:12px;color:var(--text-tertiary);">${Utils.formatDate(e.date,"datetime")}</span>\n              </span>\n            </button>\n          `).join("")}\n        </div>\n      </div>`;App.openModal(t)},PITCH_DEMO_PHONES:["07494 809272","07700 900481","07700 900612","07700 900734","07700 900845","07700 900926"],async confirmClearPitchDemo(){App.openModal('<div class="sheet-handle"></div>\n      <div class="sheet-header"><h3>Remove Demo Data?</h3><button class="btn btn-ghost btn-sm" onclick="App.closeModal()"><span class="material-symbols-rounded">close</span></button></div>\n      <div class="sheet-body">\n        <div style="font-size:14px;color:var(--text-secondary);margin-bottom:16px;">\n          This removes the sample customers and visits used for demoing the app (Ayesha Khan, James Wilson, and others), along with their visits, orders, and messages. Your own customers and visits are not affected.\n        </div>\n        <button class="btn btn-danger btn-block" onclick="ControlFeature.clearPitchDemo()">\n          <span class="material-symbols-rounded">delete_sweep</span>Remove Demo Data\n        </button>\n        <button class="btn btn-outline btn-block" style="margin-top:8px;" onclick="App.closeModal()">Cancel</button>\n      </div>')},async clearPitchDemo(){try{const e=await DB.db.customers.where("phone").anyOf(this.PITCH_DEMO_PHONES).toArray();for(const t of e)await DB.deleteCustomer(t.id);await DB.setSetting("pitchDemoSeeded",!1),App.closeModal(),Toast.show(e.length>0?`Removed ${e.length} demo customer${1===e.length?"":"s"}`:"Demo data already removed","success"),App.navigate("control")}catch(e){console.error("Clear demo data failed:",e),Toast.show("Failed to remove demo data","error")}}};App.registerFeature(ControlFeature);
